  stand(c,w,Q.getX()+.5,Q.getZ()+3.5);select(c,w,InputConstants.KEY_2,1);use(c,Q.below(),Vec3.atCenterOf(Q.below()).add(0,.499,0));await(c,w,level->clock(level,Q)!=null&&actual(level).getInventory().getItem(1).isEmpty()&&clock(level,Q).getSpeed()!=0,250,"Physical mysterious source did not pay original second clock");server.runCommand("gamemode spectator @p");server.runCommand("tp @p 65016.5 8 13.5");server.runCommand("time set 6000");c.waitFor(client->client.level.getBlockEntity(Q) instanceof CuckooClockBlockEntity clock&&clock.animationType==CuckooClockBlockEntity.Animation.SURPRISE&&clock.animationProgress.getValue()>=31&&clock.animationProgress.getValue()<43,200);verify(c,Q);look(c,Vec3.atCenterOf(Q));screenshot(c,w,"create-vulkan-cuckoo-second-original-paid-mysterious-source-real-smoke-before-genuine-surprise");await(c,w,level->LoadedLevelAccess.blockState(level,Q).isAir()&&clock(level,P)!=null&&link(level)!=null&&board(level)!=null,200,"Genuine source surprise failed actual clock consumption or damaged remote real receivers");server.runOnServer(ignored->{var level=w.getConnection().getServerLevel();var inventory=actual(level).getInventory();if(!inventory.getItem(0).isEmpty()||!inventory.getItem(1).isEmpty()||!inventory.getItem(2).isEmpty()||!inventory.getItem(3).is(AllItems.WRENCH)||level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(Q).inflate(6),item->item.getItem().is(AllBlocks.MYSTERIOUS_CUCKOO_CLOCK.asItem())).size()!=0)throw new AssertionError("Original finite paid clock/link/surprise/wrench receipts changed across native tests");});
